package io.github.danieltudose.trueclueareas;

import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

import java.awt.Color;

@ConfigGroup("trueclueareas")
public interface TrueClueAreasConfig extends Config {
	enum RenderStyle {
		TILES("Individual tiles"),
		AREA("Single area");

		private final String name;
		RenderStyle(String name) { this.name = name; }

		@Override
		public String toString() { return name; }
	}
	@ConfigSection(
			name = "General",
			description = "General display settings",
			position = -1)
	String generalSection = "general";

	@ConfigItem(
			keyName = "renderStyle",
			name = "Render style",
			description = "How to draw the highlighted area. 'Tiles' follows terrain height. 'Area' draws a flat rectangle.",
			section = generalSection,
			position = 0)
	default RenderStyle renderStyle() {
		return RenderStyle.TILES;
	}
	@ConfigSection(
			name = "Map Clues",
			description = "Settings for map clue step highlights",
			position = 0)
	String mapSection = "mapClues";

	@ConfigSection(
			name = "Emote Clues",
			description = "Settings for emote clue step highlights",
			position = 1)
	String emoteSection = "emoteClues";

	@ConfigSection(
			name = "Hot/Cold Clues",
			description = "Settings for hot/cold clue step highlights",
			position = 2)
	String hotColdSection = "hotColdClues";

	@ConfigSection(
			name = "Coordinate Clues",
			description = "Settings for coordinate clue step highlights",
			position = 3)
	String coordinateSection = "coordinateClues";

	@ConfigItem(
			keyName = "showCoordinateClues",
			name = "Show coordinate clue areas",
			description = "Highlight the dig area for coordinate clue steps",
			section = coordinateSection,
			position = 0)
	default boolean showCoordinateClues() {
		return true;
	}

	@Alpha
	@ConfigItem(
			keyName = "coordinateClueColor",
			name = "Highlight color",
			description = "Color of the coordinate clue dig area highlight",
			section = coordinateSection,
			position = 1)
	default Color coordinateClueColor() {
		return new Color(255, 107, 0, 50); // orange, semi-transparent
	}

	@ConfigItem(
			keyName = "showMapClues",
			name = "Show map clue areas",
			description = "Highlight the dig area for map clue steps",
			section = mapSection,
			position = 0)
	default boolean showMapClues() {
		return true;
	}

	@Alpha
	@ConfigItem(
			keyName = "mapClueColor",
			name = "Highlight color",
			description = "Color of the map clue dig area highlight",
			section = mapSection,
			position = 1)
	default Color mapClueColor() {
		return new Color(212, 255, 0, 50);
	}

	@ConfigItem(
			keyName = "showEmoteClues",
			name = "Show emote clue areas",
			description = "Highlight the area for emote clue steps",
			section = emoteSection,
			position = 0)
	default boolean showEmoteClues() {
		return true;
	}

	@Alpha
	@ConfigItem(
			keyName = "emoteClueColor",
			name = "Highlight color",
			description = "Color of the emote clue area highlight",
			section = emoteSection,
			position = 1)
	default Color emoteClueColor() {
		return new Color(255, 165, 0, 50);
	}

	@ConfigItem(
			keyName = "showHotColdClues",
			name = "Show hot/cold areas",
			description = "Highlight possible dig areas for hot/cold clue steps",
			section = hotColdSection,
			position = 0)
	default boolean showHotColdClues() {
		return true;
	}

	@Alpha
	@ConfigItem(
			keyName = "hotColdColor",
			name = "Highlight color",
			description = "Color of the hot/cold area highlight",
			section = hotColdSection,
			position = 1)
	default Color hotColdColor() {
		return new Color(255, 69, 69, 50);
	}

	@Range(min = 1, max = 5)
	@ConfigItem(
			keyName = "hotColdThreshold",
			name = "Show overlay when X locations remain",
			description = "Only show the hot/cold overlay when this many or fewer locations remain",
			section = hotColdSection,
			position = 2)
	default int hotColdThreshold() {
		return 2;
	}

	@ConfigSection(
			name = "Misc Clues",
			description = "Settings for miscellaneous clue step highlights (music, Sherlock, etc.)",
			position = 4)
	String miscSection = "miscClues";

	@ConfigItem(
			keyName = "showMiscClues",
			name = "Show misc clue areas",
			description = "Highlight the area for Music and some Sherlock clue steps",
			section = miscSection,
			position = 0)
	default boolean showMiscClues() {
		return true;
	}

	@Alpha
	@ConfigItem(
			keyName = "miscClueColor",
			name = "Highlight color",
			description = "Color of the misc clue area highlight",
			section = miscSection,
			position = 1)
	default Color miscClueColor() {
		return new Color(255, 165, 0, 40);
	}
}

package io.github.danieltudose.trueclueareas;

import io.github.danieltudose.trueclueareas.data.DigArea;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.plugins.cluescrolls.clues.hotcold.HotColdLocation;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.api.Point;

import javax.inject.Inject;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.util.Set;


@Slf4j
public class TrueClueAreasOverlay extends Overlay {
    private final Client client;
    private final TrueClueAreasConfig config;

    public enum ClueType {MAP, EMOTE, COORDINATE, MISC}

    private DigArea digArea = null;
    private ClueType digAreaType = null;
    @Setter
    private Set<HotColdLocation> hotColdLocations = null;

    @Inject
    public TrueClueAreasOverlay(Client client, TrueClueAreasConfig config) {
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
        this.client = client;
        this.config = config;
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (digArea != null && digAreaType != null) {
            boolean shouldShow;
            Color color;
            if (digAreaType == ClueType.MAP) {
                shouldShow = config.showMapClues();
                color = config.mapClueColor();
            } else if (digAreaType == ClueType.COORDINATE) {
                shouldShow = config.showCoordinateClues();
                color = config.coordinateClueColor();
            } else if (digAreaType == ClueType.MISC) {
            shouldShow = config.showMiscClues();
            color = config.miscClueColor();
            }
            else {
                shouldShow = config.showEmoteClues();
                color = config.emoteClueColor();
            }
            if (shouldShow) {
                int fillAlpha = Math.max(10, color.getAlpha());
                int borderAlpha = Math.min(255, fillAlpha * 2);
                Color fill   = new Color(color.getRed(), color.getGreen(), color.getBlue(), fillAlpha);
                Color border = new Color(color.getRed(), color.getGreen(), color.getBlue(), borderAlpha);
                for (int i = 0; i < digArea.getRectCount(); i++) {
                    drawArea(graphics, digArea.getSouthWestCorner(i), digArea.getNorthEastCorner(i), fill, border);
                }
            }
        }

        if (hotColdLocations != null && config.showHotColdClues()) {
            Color color = config.hotColdColor();
            int fillAlpha = Math.max(10, color.getAlpha());
            int borderAlpha = Math.min(255, fillAlpha * 2);
            Color fill   = new Color(color.getRed(), color.getGreen(), color.getBlue(), fillAlpha);
            Color border = new Color(color.getRed(), color.getGreen(), color.getBlue(), borderAlpha);
            for (HotColdLocation location : hotColdLocations) {
                java.awt.Rectangle rect = location.getRect();
                WorldPoint sw = new WorldPoint(
                        rect.x,
                        rect.y,
                        location.getWorldPoint().getPlane());
                WorldPoint ne = new WorldPoint(
                        rect.x + rect.width - 1,
                        rect.y + rect.height - 1,
                        location.getWorldPoint().getPlane());
                drawArea(graphics, sw, ne, fill, border);
            }
        }


        return null;
    }

    private void drawArea(Graphics2D graphics, WorldPoint sw, WorldPoint ne, Color fill, Color border) {
        if (config.renderStyle() == TrueClueAreasConfig.RenderStyle.TILES) {
            renderAreaAsTiles(graphics, sw, ne, fill, border);
        } else {
            renderArea(graphics, sw, ne, fill, border);
        }
    }

    private void renderArea(Graphics2D graphics,
                            WorldPoint sw, WorldPoint ne,
                            Color fillColor, Color borderColor) {
        LocalPoint swLocal = LocalPoint.fromWorld(client, sw);
        LocalPoint neLocal = LocalPoint.fromWorld(client, ne);
        if (swLocal == null || neLocal == null) return;

        final int HALF = 64;
        int x1 = swLocal.getX() - HALF;
        int y1 = swLocal.getY() - HALF;
        int x2 = neLocal.getX() + HALF;
        int y2 = neLocal.getY() + HALF;

        Point p1 = Perspective.localToCanvas(client,
                new LocalPoint(x1, y1, swLocal.getWorldView()), sw.getPlane());
        Point p2 = Perspective.localToCanvas(client,
                new LocalPoint(x1, y2, swLocal.getWorldView()), sw.getPlane());
        Point p3 = Perspective.localToCanvas(client,
                new LocalPoint(x2, y2, neLocal.getWorldView()), ne.getPlane());
        Point p4 = Perspective.localToCanvas(client,
                new LocalPoint(x2, y1, neLocal.getWorldView()), ne.getPlane());

        if (p1 == null || p2 == null || p3 == null || p4 == null) return;

        Polygon poly = new Polygon();
        poly.addPoint(p1.getX(), p1.getY());
        poly.addPoint(p2.getX(), p2.getY());
        poly.addPoint(p3.getX(), p3.getY());
        poly.addPoint(p4.getX(), p4.getY());

        graphics.setColor(fillColor);
        graphics.fill(poly);
        graphics.setColor(borderColor);
        graphics.setStroke(new BasicStroke(2));
        graphics.draw(poly);
    }

    public void setDigArea(DigArea area, ClueType type) {
        this.digArea = area;
        this.digAreaType = type;
    }

    public void clearDigArea() {
        this.digArea = null;
        this.digAreaType = null;
    }

    private void renderAreaAsTiles(Graphics2D graphics,
                                   WorldPoint sw, WorldPoint ne,
                                   Color fillColor, Color borderColor) {
        int plane = sw.getPlane();
        graphics.setStroke(new BasicStroke(1));

        for (int x = sw.getX(); x <= ne.getX(); x++) {
            for (int y = sw.getY(); y <= ne.getY(); y++) {
                LocalPoint lp = LocalPoint.fromWorld(client, new WorldPoint(x, y, plane));
                if (lp == null) continue;

                Polygon poly = Perspective.getCanvasTilePoly(client, lp);
                if (poly == null) continue;

                graphics.setColor(fillColor);
                graphics.fill(poly);
                graphics.setColor(borderColor);
                graphics.draw(poly);
            }
        }
    }

    public boolean hasDigArea() {
        return digArea != null;
    }
}

package io.github.danieltudose.trueclueareas;

import io.github.danieltudose.trueclueareas.data.emote.BeginnerEmoteClueAreas;
import io.github.danieltudose.trueclueareas.data.emote.EasyEmoteClueAreas;
import io.github.danieltudose.trueclueareas.data.emote.MediumEmoteClueAreas;
import io.github.danieltudose.trueclueareas.data.emote.HardEmoteClueAreas;
import io.github.danieltudose.trueclueareas.data.emote.EliteEmoteClueAreas;
import io.github.danieltudose.trueclueareas.data.emote.MasterEmoteClueAreas;
import static io.github.danieltudose.trueclueareas.data.map.CustomMapClueAreas.*;
import static io.github.danieltudose.trueclueareas.data.cryptic.CustomCrypticClueAreas.*;

import java.util.*;

import io.github.danieltudose.trueclueareas.data.DigArea;
import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.gameval.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.cluescrolls.ClueScrollPlugin;
import net.runelite.client.plugins.cluescrolls.clues.*;
import net.runelite.client.plugins.cluescrolls.clues.hotcold.HotColdLocation;
import net.runelite.client.ui.overlay.OverlayManager;

import javax.inject.Inject;

import static net.runelite.client.plugins.cluescrolls.clues.Enemy.*;

@Slf4j
@PluginDescriptor(
		name = "True Clue Areas",
		description = "Highlights the true dig/emote areas for clue scroll steps",
		tags = {"clue", "scroll", "overlay", "dig", "area", "emote", "clues"})

public class TrueClueAreasPlugin extends Plugin {
	@Inject private net.runelite.client.callback.ClientThread clientThread;
	@Inject private Client client;
	@Inject private TrueClueAreasConfig config;
	@Inject private OverlayManager overlayManager;
	@Inject private TrueClueAreasOverlay overlay;
	@Inject private PluginManager pluginManager;

	private static final Map<String, DigArea> ALL_EMOTE_AREAS;
	private ClueScroll lastKnownClue = null;

	static {
		Map<String, DigArea> emoteAreas = new HashMap<>();
		emoteAreas.putAll(BeginnerEmoteClueAreas.AREAS);
		emoteAreas.putAll(EasyEmoteClueAreas.AREAS);
		emoteAreas.putAll(MediumEmoteClueAreas.AREAS);
		emoteAreas.putAll(HardEmoteClueAreas.AREAS);
		emoteAreas.putAll(EliteEmoteClueAreas.AREAS);
		emoteAreas.putAll(MasterEmoteClueAreas.AREAS);
		ALL_EMOTE_AREAS = Collections.unmodifiableMap(emoteAreas);
	}

		private boolean manualClear = false;

	private void clearAll() {
		overlay.clearDigArea();
		overlay.setHotColdLocations(null);
		manualClear = true;
	}

	@Override
	protected void startUp() {
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown() {
		overlayManager.remove(overlay);
		clearAll();
		lastKnownClue = null;
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event) {
		switch (event.getGroupId()) {
			case 203: // Standard Text Clue Interface
				handleTextClue();
				break;
			case 231: // NPC Dialog (Uri)
				handleUriDialog();
				break;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event) {
		ClueScrollPlugin cluePlugin = getClueScrollPlugin();
		ClueScroll current = cluePlugin != null ? cluePlugin.getClue() : null;

		if (current != lastKnownClue) {
			lastKnownClue = current;
			manualClear = false;
			onClueChanged(current, cluePlugin);
		} else if (current != null && !overlay.hasDigArea() && !manualClear) {
			onClueChanged(current, cluePlugin);
		}

		if (current instanceof HotColdClue) {
			updateHotColdFromBasePlugin((HotColdClue) current, cluePlugin);
		} else {
			overlay.setHotColdLocations(null);
		}
	}

	private void onClueChanged(ClueScroll newClue, ClueScrollPlugin cluePlugin) {
		if (newClue == null) {
			clearAll();
			return;
		}

		if (newClue instanceof EmoteClue) {
			EmoteClue emoteClue = (EmoteClue) newClue;
			DigArea area = ALL_EMOTE_AREAS.entrySet().stream()
					.filter(e -> e.getKey().equalsIgnoreCase(emoteClue.getText()))
					.map(Map.Entry::getValue)
					.findFirst().orElse(null);
			if (area != null) {
				overlay.setDigArea(area, TrueClueAreasOverlay.ClueType.EMOTE);
			}
			return;
		}

		if (newClue instanceof MapClue) {
			MapClue mapClue = (MapClue) newClue;
			if (ELITE_MAP_CLUE_IDS.contains(mapClue.getItemId())) return;
			if (!mapClue.isRequiresSpade()) return;
			WorldPoint loc = mapClue.getLocation(cluePlugin);
			if (loc == null) return;
			DigArea custom = MAP_STEPS_CUSTOM_AREAS.get(loc);
			overlay.setDigArea(custom != null ? custom : new DigArea(loc, 3), TrueClueAreasOverlay.ClueType.MAP);
			return;
		}

		if (newClue instanceof CrypticClue) {
			CrypticClue crypticClue = (CrypticClue) newClue;

			WorldPoint loc = crypticClue.getLocation(cluePlugin);
			if (loc != null) {
				DigArea customArea = CRYPTIC_STEPS_CUSTOM_AREAS.get(loc);
				if (customArea != null) {
					overlay.setDigArea(customArea, TrueClueAreasOverlay.ClueType.MAP);
					return;
				}
			}

			if (!crypticClue.isRequiresSpade()) return;
			if (loc == null) return;
			boolean isMaster = crypticClue.getItemIds().contains(ItemID.TRAIL_CLUE_MASTER);
			overlay.setDigArea(new DigArea(loc, isMaster ? 7 : 3), TrueClueAreasOverlay.ClueType.MAP);
			return;
		}

		if (newClue instanceof ThreeStepCrypticClue) {
			handleThreeStepCryptic((ThreeStepCrypticClue) newClue, cluePlugin);
			return;
		}

		if (newClue instanceof CoordinateClue) {
			CoordinateClue coordClue = (CoordinateClue) newClue;
			if (coordClue.getEnemy() == ARMADYLEAN_OR_BANDOSIAN_GUARD
					|| coordClue.getEnemy() == ARMADYLEAN_GUARD
					|| coordClue.getEnemy() == BANDOSIAN_GUARD) return;
			WorldPoint loc = coordClue.getLocation(cluePlugin);
			if (loc == null) return;
			overlay.setDigArea(new DigArea(loc, 3), TrueClueAreasOverlay.ClueType.COORDINATE);
			return;
		}

		if (newClue instanceof MusicClue) {
			overlay.setDigArea(
					new DigArea(new WorldPoint(2986, 3380, 0), new WorldPoint(2994, 3388, 0)),
					TrueClueAreasOverlay.ClueType.MISC);
		}
	}


	private void updateHotColdFromBasePlugin(HotColdClue hotColdClue, ClueScrollPlugin cluePlugin) {
		WorldPoint[] locations = hotColdClue.getLocations(cluePlugin);

		Set<HotColdLocation> matched = new HashSet<>();
		for (WorldPoint wp : locations) {
			for (HotColdLocation loc : HotColdLocation.values()) {
				if (loc.getWorldPoint().equals(wp)) {
					matched.add(loc);
					break;
				}
			}
		}

		if (!matched.isEmpty() && matched.size() <= config.hotColdThreshold()) {
			overlay.setHotColdLocations(matched);
		} else {
			overlay.setHotColdLocations(null);
		}
	}

	private ClueScrollPlugin getClueScrollPlugin() {
		return pluginManager.getPlugins().stream()
				.filter(p -> p instanceof ClueScrollPlugin)
				.map(p -> (ClueScrollPlugin) p)
				.findFirst()
				.orElse(null);
	}

	private void handleTextClue() {
		clientThread.invokeLater(() -> {
			net.runelite.api.widgets.Widget clueWidget = client.getWidget(203, 2);
			if (clueWidget == null || clueWidget.getText() == null || clueWidget.getText().isEmpty()) return;

			String text = clueWidget.getText()
					.replaceAll("(?i)<br\\s*/?>", " ")
					.replaceAll("<[^>]*>", "")
					.replaceAll("\\s+", " ")
					.replace('\u2019', '\'')
					.trim();

			DigArea emoteArea = ALL_EMOTE_AREAS.entrySet().stream()
					.filter(e -> e.getKey().equalsIgnoreCase(text))
					.map(Map.Entry::getValue)
					.findFirst().orElse(null);
			if (emoteArea != null) {
				overlay.setDigArea(emoteArea, TrueClueAreasOverlay.ClueType.EMOTE);
			}
			// Nothing else. All other types are handled by onClueChanged via onGameTick.
		});
	}

	private void handleThreeStepCryptic(ThreeStepCrypticClue threeStep, ClueScrollPlugin cluePlugin) {
		List<DigArea> areas = new ArrayList<>();

		for (Map.Entry<CrypticClue, Boolean> step : threeStep.getClueSteps()) {
			if (step.getValue()) continue;        // step already completed
			CrypticClue sub = step.getKey();
			if (!sub.isRequiresSpade()) continue; // NPC or object step, not a dig

			WorldPoint loc = sub.getLocation(cluePlugin);
			if (loc == null) continue;

			DigArea custom = CRYPTIC_STEPS_CUSTOM_AREAS.get(loc);
			areas.add(custom != null ? custom : new DigArea(loc, 7));
		}

		if (!areas.isEmpty()) {
			overlay.setDigArea(DigArea.combine(areas), TrueClueAreasOverlay.ClueType.MAP);
		} else {
			overlay.clearDigArea();
		}
	}


	private void handleUriDialog() {
		clientThread.invokeLater(() -> {
			net.runelite.api.widgets.Widget nameWidget = client.getWidget(231, 4);
			if (nameWidget != null && "Uri".equals(nameWidget.getText())) {
				clearAll();
			}
		});
	}

	@Subscribe
	public void onGameStateChanged(net.runelite.api.events.GameStateChanged event) {
		if (event.getGameState() == GameState.LOGIN_SCREEN) {
			clearAll();
		}
	}

	@Provides
	TrueClueAreasConfig provideConfig(ConfigManager configManager) {
		return configManager.getConfig(TrueClueAreasConfig.class);
	}
}

package io.github.danieltudose.trueclueareas.data;

import net.runelite.api.coords.WorldPoint;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

public class DigArea {
    private final List<WorldPoint> southWestCorners;
    private final List<WorldPoint> northEastCorners;

    // Single rectangle from explicit corners
    public DigArea(WorldPoint sw, WorldPoint ne) {
        this.southWestCorners = Collections.singletonList(sw);
        this.northEastCorners = Collections.singletonList(ne);
    }

    // Single rectangle from center + square size
    public DigArea(WorldPoint center, int size) {
        this(center, size, size);
    }

    // Single rectangle from center + width/height
    public DigArea(WorldPoint center, int width, int height) {
        int halfW = width / 2;
        int halfH = height / 2;
        this.southWestCorners = Collections.singletonList(
                new WorldPoint(center.getX() - halfW, center.getY() - halfH, center.getPlane()));
        this.northEastCorners = Collections.singletonList(
                new WorldPoint(center.getX() + halfW, center.getY() + halfH, center.getPlane()));
    }

    // Two separate rectangles — for cases like the composite emote areas
    public DigArea(WorldPoint sw1, WorldPoint ne1, WorldPoint sw2, WorldPoint ne2) {
        this.southWestCorners = Arrays.asList(sw1, sw2);
        this.northEastCorners = Arrays.asList(ne1, ne2);
    }

    // Internal constructor used by combine()
    private DigArea(List<WorldPoint> sw, List<WorldPoint> ne) {
        this.southWestCorners = sw;
        this.northEastCorners = ne;
    }

    // Merges any number of DigAreas into one (e.g. multiple unfinished
    // sub-steps of a ThreeStepCrypticClue, each shown at once)
    public static DigArea combine(List<DigArea> areas) {
        List<WorldPoint> sw = new java.util.ArrayList<>();
        List<WorldPoint> ne = new java.util.ArrayList<>();
        for (DigArea area : areas) {
            for (int i = 0; i < area.getRectCount(); i++) {
                sw.add(area.getSouthWestCorner(i));
                ne.add(area.getNorthEastCorner(i));
            }
        }
        return new DigArea(sw, ne);
    }

    public int getRectCount() {
        return southWestCorners.size();
    }

    public WorldPoint getSouthWestCorner() {
        return southWestCorners.get(0);
    }

